import * as T from 'three';
import{seeded}from'./geometry.js';
export function createAtmosphere(ctx,materials,env){
 const{scene,renderer,camera,economy}=ctx,{M,canvas}=materials,{rr}=seeded(8151961);let blend=0;
 const ambient=new T.HemisphereLight('#b3c9e2','#726264',1.2);scene.add(ambient);
 const sun=new T.DirectionalLight('#ffd1a0',3.6);sun.position.set(-28,22,35);sun.target.position.set(0,3,0);scene.add(sun,sun.target);sun.castShadow=true;sun.shadow.mapSize.set(economy?1024:2048,economy?1024:2048);Object.assign(sun.shadow.camera,{left:-28,right:28,top:25,bottom:-24,near:1,far:105});sun.shadow.bias=-.00012;sun.shadow.normalBias=.035;sun.shadow.radius=3;
 const fill=new T.DirectionalLight('#9bbce0',.55);fill.position.set(22,20,-22);scene.add(fill);
 const skyUniforms={upper:{value:new T.Color('#8caabf')},horizon:{value:new T.Color('#ead1be')},lower:{value:new T.Color('#e3bc9b')}};
 const sky=new T.Mesh(new T.SphereGeometry(180,32,20),new T.ShaderMaterial({side:T.BackSide,depthWrite:false,uniforms:skyUniforms,vertexShader:'varying vec3 vDir;void main(){vDir=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec3 vDir;uniform vec3 upper,horizon,lower;void main(){float y=normalize(vDir).y+.67;vec3 c=mix(lower,horizon,smoothstep(-.3,.03,y));c=mix(c,upper,smoothstep(.02,.8,y));gl_FragColor=vec4(c,1.);\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}'}));sky.name='Winter atmospheric sky';sky.renderOrder=-1000;sky.material.depthTest=false;sky.frustumCulled=false;scene.add(sky);
 // A generated equirectangular sky supplies actual roughness-dependent PBR environment response.
 const skyMap=canvas(1024,512,(c,w,h)=>{const grad=c.createLinearGradient(0,0,0,h);grad.addColorStop(0,'#718da9');grad.addColorStop(.46,'#c6d0d2');grad.addColorStop(.57,'#e8c4a2');grad.addColorStop(1,'#5d6469');c.fillStyle=grad;c.fillRect(0,0,w,h);const g=c.createRadialGradient(250,260,0,250,260,110);g.addColorStop(0,'#ffe4bdaa');g.addColorStop(1,'#ffe4bd00');c.fillStyle=g;c.fillRect(0,0,w,h);});skyMap.mapping=T.EquirectangularReflectionMapping;const pmrem=new T.PMREMGenerator(renderer),environment=pmrem.fromEquirectangular(skyMap);scene.environment=environment.texture;scene.environmentIntensity=.65;pmrem.dispose();
 scene.fog=new T.Fog('#c6bfc1',68,160);
 const lightPositions=[env.lamps[2],env.lamps[6],[-3.6,2.5,6.5],[5.6,2.6,5.8],[-8.8,3,-3.7],[11.4,2.7,-1.4]];
 const lights=lightPositions.map((p,i)=>{const l=new T.PointLight('#ffbf79',i<2?10:17,i<2?6:10,2);l.position.set(...p);scene.add(l);return l;});
 const glow=canvas(64,64,(c,w)=>{const g=c.createRadialGradient(32,32,0,32,32,32);g.addColorStop(0,'#fff8df');g.addColorStop(.12,'#ffe1aabb');g.addColorStop(.4,'#ffad4e2f');g.addColorStop(1,'#ffad4e00');c.fillStyle=g;c.fillRect(0,0,w,w);});
 const glowMat=new T.SpriteMaterial({map:glow,color:'#ffc98b',transparent:true,depthWrite:false,blending:T.AdditiveBlending,opacity:.28});const glowRoot=new T.Group();scene.add(glowRoot);for(const p of env.lamps){const s=new T.Sprite(glowMat);s.position.set(...p);s.scale.set(.65,.65,1);glowRoot.add(s);}
 // Camera-depth-varying snowfall, soft round flakes with fade before ground and respawn.
 const count=economy?950:1900,ps=[],seed=[],sizes=[];for(let i=0;i<count;i++){ps.push(rr(-24,24),rr(.7,25),rr(-20,20));seed.push(rr(0,1));sizes.push(rr(.065,.14));}
 const sg=new T.BufferGeometry();sg.setAttribute('position',new T.Float32BufferAttribute(ps,3));sg.setAttribute('aSeed',new T.Float32BufferAttribute(seed,1));sg.setAttribute('aSize',new T.Float32BufferAttribute(sizes,1));
 const snowMat=new T.ShaderMaterial({uniforms:{uTime:{value:0},uPixel:{value:1},uVisible:{value:1},uColor:{value:new T.Color('#f1eee7')}},vertexShader:`uniform float uTime,uPixel;attribute float aSeed,aSize;varying float vAlpha;void main(){vec3 p=position;float fall=uTime*(.8+aSeed*.95);p.y=.6+mod(position.y-.6-fall+250.,24.4);p.x+=sin(uTime*.16+aSeed*25.)*.65+sin(uTime*.43+aSeed*9.)*.25;p.z+=cos(uTime*.19+aSeed*31.)*.4;vec4 mv=modelViewMatrix*vec4(p,1.);gl_Position=projectionMatrix*mv;gl_PointSize=clamp(aSize*uPixel*1650./max(6.,-mv.z),1.1,6.0);vAlpha=smoothstep(.65,1.7,p.y)*smoothstep(25.,23.,p.y)*(.58+aSeed*.32);}`,fragmentShader:`uniform float uVisible;uniform vec3 uColor;varying float vAlpha;void main(){float d=length(gl_PointCoord-.5);float a=(1.-smoothstep(.12,.5,d))*vAlpha*uVisible;if(a<.015)discard;gl_FragColor=vec4(uColor,a);\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}`,transparent:true,depthWrite:false});
 const flakes=new T.Points(sg,snowMat);flakes.name='Layered drifting snowfall';flakes.frustumCulled=false;scene.add(flakes);
 // Continuous micro-ripples alter normals, not a field of disconnected white dashes.
 const waterUniforms={uWaterTime:{value:0}};
 const waterMat=new T.MeshPhysicalMaterial({color:'#395969',roughness:.43,metalness:.18,clearcoat:.12,clearcoatRoughness:.45,envMapIntensity:.65});waterMat.name='Cold Moskva water';materials.mats.push(waterMat);
 waterMat.onBeforeCompile=shader=>{shader.uniforms.uWaterTime=waterUniforms.uWaterTime;shader.vertexShader='uniform float uWaterTime;varying vec3 vWaterPosition;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvWaterPosition=position; transformed.z += .013*sin(position.x*2.3+uWaterTime*.7)+.009*cos(position.y*3.1-uWaterTime*.48);');shader.fragmentShader='uniform float uWaterTime;varying vec3 vWaterPosition;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <normal_fragment_maps>','#include <normal_fragment_maps>\nnormal=normalize(normal+vec3(.024*cos(vWaterPosition.x*2.3+vWaterPosition.y*1.7+uWaterTime*.7)+.018*sin(vWaterPosition.x*3.6-vWaterPosition.y*2.3+uWaterTime*.45),.025*sin(vWaterPosition.y*3.1-vWaterPosition.x*1.6-uWaterTime*.48),0.));');};
 const water=new T.Mesh(new T.PlaneGeometry(env.river.width,env.river.depth,100,20),waterMat);water.rotation.x=-Math.PI/2;water.position.set(env.river.x,env.river.level,env.river.z);water.receiveShadow=true;scene.add(water);
 // Localized shore ice, closed geometry above water; never crosses into square.
 const iceMat=new T.MeshPhysicalMaterial({color:'#b6cdd5',roughness:.47,metalness:.05,clearcoat:.25});materials.mats.push(iceMat);const ice=new T.InstancedMesh(new T.CylinderGeometry(1,1,.045,7),iceMat,22),d=new T.Object3D();for(let i=0;i<22;i++){d.position.set(rr(-20,20),.44,rr(13,13.5));d.rotation.set(0,rr(0,6.28),0);d.scale.set(rr(.2,.7),1,rr(.12,.4));d.updateMatrix();ice.setMatrixAt(i,d.matrix);}ice.receiveShadow=true;scene.add(ice);
 function update(dt,state){sky.position.copy(camera.position);blend=T.MathUtils.damp(blend,state.mode==='blue'?1:0,2.1,dt);const n=blend;ambient.color.set('#b4cde3').lerp(new T.Color('#8cadd7'),n);ambient.intensity=T.MathUtils.lerp(.9,.8,n);ambient.groundColor.set('#7c6960').lerp(new T.Color('#434f6e'),n);sun.intensity=T.MathUtils.lerp(4.2,.32,n);sun.color.set('#ffd0a2').lerp(new T.Color('#9bb8df'),n);sun.position.set(T.MathUtils.lerp(-38,-32,n),T.MathUtils.lerp(17,36,n),30);fill.intensity=T.MathUtils.lerp(.34,.4,n);renderer.toneMappingExposure=T.MathUtils.lerp(1.06,1.16,n);scene.environmentIntensity=T.MathUtils.lerp(.68,.47,n);
  skyUniforms.upper.value.set('#8caabf').lerp(new T.Color('#233854'),n);skyUniforms.horizon.value.set('#ead1be').lerp(new T.Color('#8296b0'),n);skyUniforms.lower.value.set('#e3bc9b').lerp(new T.Color('#a28c93'),n);scene.fog.color.set('#c6bfc1').lerp(new T.Color('#71839d'),n);
  M.window.emissiveIntensity=T.MathUtils.lerp(.22,1.2,n);M.window.color.set('#8d8070').lerp(new T.Color('#d8a96c'),n);M.lamp.emissiveIntensity=T.MathUtils.lerp(1.5,3.0,n);glowMat.opacity=T.MathUtils.lerp(.22,.50,n);lights.forEach((l,i)=>l.intensity=(i<2?9:16)*(.45+n*.55));
  snowMat.uniforms.uTime.value=state.snowTime;snowMat.uniforms.uPixel.value=renderer.getPixelRatio();snowMat.uniforms.uVisible.value=state.snow?1:0;waterUniforms.uWaterTime.value=state.time;
 }
 return{update,sun,water,flakes,diagnostics:()=>({blend,shadowResolution:sun.shadow.mapSize.x,snowCount:count,lighting:'PBR · ACES · generated environment'}),dispose(){environment.dispose();glowMat.dispose();sky.geometry.dispose();sky.material.dispose();snowMat.dispose();}};
}
